source_text:
\spheader 223Yi\dvAnew{2014} 
Let $E\subseteq\Bbb R$ be a non-negligible measurable set. 
Show that $0$ belongs to the interior of $E-E=\{x-y:x$, $y\in E\}$.
%223B
}%end of exercises
     
\endnotes{

target_text:
\spheader 223Yi\dvAnew{2014}
Misalkan $E\subseteq\Bbb R$ suatu himpunan terukur tak terabaikan.
Tunjukkan bahwa $0$ termasuk dalam interior
$E-E=\{x-y:x$, $y\in E\}$.
%223B
}%end of exercises

\endnotes{
